+static int ax88179a_set_features(struct net_device *net, netdev_features_t features)
+{
+	u8 tmp;
+	int ret;
+	struct usbnet *dev = netdev_priv(net);
+	netdev_features_t changed = net->features ^ features;
+
+	ret = ax88179_set_features(net, features);
+	if (ret)
