 	ret = dw_dp_link_enable(dp);
 	if (ret < 0) {
@@ -1737,7 +1742,8 @@ static void dw_dp_bridge_atomic_disable(struct drm_bridge *bridge,
 
 	dw_dp_video_disable(dp);
